-- Data dummy website bencana banjir (MySQL / MariaDB, siap import di phpMyAdmin XAMPP)
CREATE DATABASE IF NOT EXISTS banjir_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE banjir_db;
SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS orang_hilang, posko, kejadian_banjir, potensi_banjir, artikel_edukasi, kabupaten, provinsi;
SET FOREIGN_KEY_CHECKS = 1;

CREATE TABLE provinsi(
  kode VARCHAR(5) PRIMARY KEY, nama VARCHAR(100) NOT NULL, pulau VARCHAR(50), lat DOUBLE, lon DOUBLE
) ENGINE=InnoDB;

CREATE TABLE kabupaten(
  id INT AUTO_INCREMENT PRIMARY KEY, kode_provinsi VARCHAR(5) NOT NULL,
  nama VARCHAR(120) NOT NULL, jenis VARCHAR(20), lat DOUBLE, lon DOUBLE,
  FOREIGN KEY (kode_provinsi) REFERENCES provinsi(kode)
) ENGINE=InnoDB;

CREATE TABLE potensi_banjir(
  id INT AUTO_INCREMENT PRIMARY KEY, id_kabupaten INT NOT NULL, periode VARCHAR(30) NOT NULL,
  tingkat ENUM('Tinggi','Menengah','Rendah','Aman','Non Banjir') NOT NULL,
  sumber VARCHAR(255), tanggal_update DATE,
  FOREIGN KEY (id_kabupaten) REFERENCES kabupaten(id)
) ENGINE=InnoDB;

CREATE TABLE kejadian_banjir(
  id INT AUTO_INCREMENT PRIMARY KEY, id_kabupaten INT NOT NULL, tanggal DATE NOT NULL, durasi_hari INT,
  penyebab VARCHAR(100), tinggi_air_cm INT, korban_meninggal INT, korban_hilang INT, korban_luka INT,
  pengungsi INT, rumah_terendam INT, kerugian_miliar_rp DECIMAL(10,1), keterangan TEXT, is_dummy TINYINT DEFAULT 1,
  FOREIGN KEY (id_kabupaten) REFERENCES kabupaten(id)
) ENGINE=InnoDB;

CREATE TABLE posko(
  id INT AUTO_INCREMENT PRIMARY KEY, id_kabupaten INT, nama VARCHAR(150), alamat VARCHAR(255),
  lat DOUBLE, lon DOUBLE, kapasitas INT, kontak VARCHAR(30), status VARCHAR(20), is_dummy TINYINT DEFAULT 1,
  FOREIGN KEY (id_kabupaten) REFERENCES kabupaten(id)
) ENGINE=InnoDB;

CREATE TABLE orang_hilang(
  id INT AUTO_INCREMENT PRIMARY KEY, id_kejadian INT, nama VARCHAR(120), usia INT, jenis_kelamin CHAR(1),
  ciri_ciri TEXT, terakhir_terlihat_di VARCHAR(255), tanggal_hilang DATE, nama_pelapor VARCHAR(120),
  kontak_pelapor VARCHAR(30), status ENUM('Dicari','Ditemukan selamat','Ditemukan meninggal') NOT NULL,
  tanggal_update DATE, is_dummy TINYINT DEFAULT 1,
  FOREIGN KEY (id_kejadian) REFERENCES kejadian_banjir(id)
) ENGINE=InnoDB;

CREATE TABLE artikel_edukasi(
  id INT AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(100) UNIQUE, kategori VARCHAR(50), judul VARCHAR(200),
  ringkasan VARCHAR(255), isi TEXT, sumber_rujukan VARCHAR(255)
) ENGINE=InnoDB;








