INSERT INTO artikel_edukasi (id,slug,kategori,judul,ringkasan,isi,sumber_rujukan) VALUES (1,'apa-itu-banjir','Dasar','Apa Itu Banjir?','Pengertian banjir dan jenis-jenisnya.','Banjir adalah meluapnya air yang menggenangi daratan yang biasanya kering, akibat debit air melebihi kapasitas saluran seperti sungai, drainase, atau danau. Jenis umum: banjir sungai, banjir bandang, banjir rob (pasang laut), banjir genangan perkotaan, dan banjir lahar.','[Dummy] Verifikasi dengan BNPB/BMKG sebelum dipublikasikan');
INSERT INTO artikel_edukasi (id,slug,kategori,judul,ringkasan,isi,sumber_rujukan) VALUES (2,'penyebab-banjir','Dasar','Penyebab Banjir','Faktor alam dan manusia penyebab banjir.','Faktor alam: curah hujan tinggi, La Nina, pasang laut, topografi cekung. Faktor manusia: penebangan hutan di hulu, alih fungsi lahan resapan, sampah menyumbat drainase, permukiman di bantaran sungai, dan penurunan muka tanah.','[Dummy] Verifikasi dengan BNPB/BMKG');
INSERT INTO artikel_edukasi (id,slug,kategori,judul,ringkasan,isi,sumber_rujukan) VALUES (3,'mitigasi-sebelum-banjir','Mitigasi','Mitigasi Sebelum Banjir','Persiapan sebelum musim hujan.','Bersihkan saluran air, tanam pohon dan buat biopori, pantau peringatan dini BMKG, siapkan tas siaga bencana (dokumen, obat, senter, makanan), kenali jalur evakuasi dan lokasi posko, tinggikan perabot dan matikan listrik jika air naik.','[Dummy] Verifikasi dengan BNPB');
INSERT INTO artikel_edukasi (id,slug,kategori,judul,ringkasan,isi,sumber_rujukan) VALUES (4,'saat-banjir','Mitigasi','Yang Dilakukan Saat Banjir','Langkah keselamatan saat banjir terjadi.','Matikan listrik dan gas, segera menuju tempat tinggi/posko, jangan menerjang arus air, jauhi tiang listrik, utamakan anak-anak, lansia, dan penyandang disabilitas, serta hubungi BPBD/112 bila perlu bantuan.','[Dummy] Verifikasi dengan BNPB');
INSERT INTO artikel_edukasi (id,slug,kategori,judul,ringkasan,isi,sumber_rujukan) VALUES (5,'pasca-banjir','Penanggulangan','Penanggulangan Pasca Banjir','Pemulihan setelah banjir surut.','Periksa kondisi bangunan dan instalasi listrik sebelum kembali, bersihkan lumpur, cuci perabot dengan disinfektan, waspadai penyakit (diare, leptospirosis, ISPA), dan laporkan kerusakan ke kelurahan/BPBD untuk pendataan bantuan.','[Dummy] Verifikasi dengan BNPB/Kemenkes');
INSERT INTO artikel_edukasi (id,slug,kategori,judul,ringkasan,isi,sumber_rujukan) VALUES (6,'membaca-peta-rawan','Data','Cara Membaca Peta Potensi Banjir BMKG','Arti tingkat Tinggi, Menengah, Rendah, Aman, Non Banjir.','Peta prakiraan BMKG membagi wilayah menjadi lima kategori: Tinggi (merah), Menengah (kuning), Rendah (hijau), Aman (cokelat), dan Non Banjir (putih). Data disusun per kabupaten/kota hingga tingkat kecamatan dan diperbarui berkala.','Dokumen BMKG: Prediksi Daerah Potensi Banjir (update 10 Des 2025)');
